using System;using System.IO;using IdleIntelligence.Core;using NUnit.Framework;using UnityEngine;
namespace IdleIntelligence.Tests {
 public sealed class CrashLedgerTests {
 [Test]public void MarksLimitsFailuresVisibilityAndCleanExitMatchActualSourceRecorder(){var expected=JsonUtility.FromJson<CrashSession>(File.ReadAllText(Path.Combine(Application.dataPath,"IdleIntelligence/Tests/EditMode/CrashReference.json")));double now=1000000;var ledger=new CrashLedger(now,"native","run-0","",null);for(int i=0;i<125;i++){now++;double start=ledger.Begin("actions","buy",now,"run-0");now+=3;ledger.End("actions","buy",start,now,3);}for(int i=0;i<25;i++){now++;double start=ledger.Begin("ticks","simulation",now,"run-0");now+=2;ledger.End("ticks","simulation",start,now,2);ledger.Visibility(i%2==1?"foreground":"background",now);ledger.Failure("save-failed","failure-"+i,"",now);}ledger.Heartbeat(now,120);ledger.SetRunId("run-1");ledger.CleanExit(now);var actual=ledger.Current;Assert.That(actual.cleanExit,Is.EqualTo(expected.cleanExit));Assert.That(actual.sessionEndedAt,Is.EqualTo(expected.sessionEndedAt));Assert.That(actual.lastUiHeartbeat,Is.EqualTo(expected.lastUiHeartbeat));Assert.That(actual.renderCount,Is.EqualTo(expected.renderCount));Assert.That(actual.runId,Is.EqualTo(expected.runId));foreach(string target in new[]{"actions","ticks"}){var field=typeof(CrashSession).GetField(target);var a=(CrashMark[])field.GetValue(actual);var e=(CrashMark[])field.GetValue(expected);Assert.That(a.Length,Is.EqualTo(e.Length),target);for(int i=0;i<a.Length;i++){Assert.That(a[i].at,Is.EqualTo(e[i].at));Assert.That(a[i].name,Is.EqualTo(e[i].name));Assert.That(a[i].phase,Is.EqualTo(e[i].phase));Assert.That(a[i].durationMs,Is.EqualTo(e[i].durationMs));}}Assert.That(actual.failures.Length,Is.EqualTo(expected.failures.Length));for(int i=0;i<actual.failures.Length;i++)Assert.That(actual.failures[i].message,Is.EqualTo(expected.failures[i].message));Assert.That(actual.visibility.Length,Is.EqualTo(expected.visibility.Length));}
 [Test]public void DiagnosticPersistenceFailureNeverThrowsIntoGameplay(){var ledger=new CrashLedger(1000000,"test","0","",_=>throw new IOException("full disk"));Assert.DoesNotThrow(()=>{double start=ledger.Begin("actions","tap",1001000,"0");ledger.End("actions","tap",start,1001001,1);ledger.Failure("save-failed","error","",1001001);ledger.CleanExit(1001002);});}
 }
}
